package com.collabspace.service; import com.collabspace.dto.AuthDtos.UserResponse;import com.collabspace.dto.UserDtos.UpdateProfileRequest;import com.collabspace.entity.User;import com.collabspace.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor public class UserService {private final UserRepository users;private final CurrentUserService current;private final AuthService auth; @Transactional public UserResponse update(UpdateProfileRequest r){User u=current.get();if(!u.getEmail().equalsIgnoreCase(r.email())&&users.existsByEmail(r.email().toLowerCase()))throw new IllegalArgumentException("Email already in use");if(!u.getUsername().equals(r.username())&&users.existsByUsername(r.username()))throw new IllegalArgumentException("Username already in use");u.setUsername(r.username().trim());u.setEmail(r.email().trim().toLowerCase());u.setProfilePicture(r.profilePicture());return auth.toDto(u);}}